// Mock Source/Lease (matching the interface in src/source.ts) that records every
// open()/read()/close() call and can inject failures.
function makeSource(opts = {}) {
  const values = opts.values ? opts.values.slice() : [];
  const state = { opens: 0, reads: 0, closes: 0, openAfterFirstNext: false };
  let firstNextSeen = false;
  const source = {
    open: async () => {
      state.opens++;
      state.openAfterFirstNext = firstNextSeen;
      if (opts.openError) throw opts.openError;
      return {
        read: async () => {
          state.reads++;
          if (opts.readError) throw opts.readError;
          const v = values.shift();
          return v === undefined ? null : v;
        },
        close: async () => {
          state.closes++;
          if (opts.closeError) throw opts.closeError;
        },
      };
    },
  };
  return { source, state, markFirstNext: () => { firstNextSeen = true; } };
}

async function rejects(fn, expectedError) {
  await assert.rejects(fn, (err) => err === expectedError);
}

