  {
    const readError = new Error('read blew up');
    const closeError = new Error('close blew up');
    const { source, state } = makeSource({ values: ['a'], readError, closeError });
    const it = new EventService(source).stream();
    assert.equal((await it.next()).value, 'A');
    await rejects(() => it.next(), readError);
    assert.equal(state.closes, 1, 'close attempted despite read failure');
  }

  // 8. Mapper failure: closed exactly once, mapper exception propagated
  //    (also preserved when close fails).
  {
    const mapperError = new Error('mapper blew up');
    const mapper = () => { throw mapperError; };
    const { source, state } = makeSource({ values: ['a'] });
    await rejects(async () => {
      for await (const value of new EventService({ ...source, __mapper: mapper }).stream()) void value;
