    await rejects(async () => {
      for await (const value of new EventService(source, mapper).stream()) void value;
    }, mapperError);
    assert.equal(state.reads, 1);
    assert.equal(state.closes, 1);
  }

  // 9. Mapper failure with close failure: original exception preserved.
  {
    const mapperError = new Error('mapper blew up');
    const closeError = new Error('close blew up');
    const { source, state } = makeSource({ values: ['a'], closeError });
    const it = new EventService(source, () => { throw mapperError; });
    await rejects(() => it.next(), mapperError);
    assert.equal(state.closes, 1);
  }

  // 10. Consumer-injected throw: closed exactly once, injected exception propagated
  //     (also preserved when close fails).
  {
    const injected = new Error('injected');
    for (const closeError of [undefined, new Error('close blew up')]) {
      const { source, state } = makeSource({ values: ['a', 'b'], closeError });
      const it = new EventService(source).stream();
      assert.equal((await it.next()).value, 'A');
      await rejects(() => it.throw(injected), injected);
      assert.equal(state.closes, 1, 'closed exactly once on injected throw');
    }
  }

  // 11. Close failure on normal exhaustion is propagated.
  {
    const closeError = new Error('close blew up');
    const { source, state } = makeSource({ values: ['a', null], closeError });
    await rejects(async () => {
      for await (const value of new EventService(source).stream()) void value;
    }, closeError);
    assert.equal(state.closes, 1);
  }

  // 12. Close failure on consumer break is propagated out of the loop.
  {
    const closeError = new Error('close blew up');
    const { source, state } = makeSource({ values: ['a', null], closeError });
    await rejects(async () => {
      for await (const value of new EventService(source).stream()) {
        void value;
        break;
      }
    }, closeError);
    assert.equal(state.closes, 1);
  }

  // 13. Open failure: nothing to close, error propagated on first iteration.
  {
    const openError = new Error('open blew up');
    const { source, state } = makeSource({ openError });
    const it = new EventService(source).stream();
    await rejects(() => it.next(), openError);
    assert.equal(state.closes, 0);
  }

  // 14. return() racing an in-flight next(): the pending next still receives its
  //     value and the lease is still closed exactly once.
  {
    const { source, state } = makeSource({ values: ['a', null] });
    const it = new EventService(source).stream();
    const pendingNext = it.next();
    const pendingReturn = it.return();
    assert.deepEqual(await pendingNext, { value: 'A', done: false });
    assert.deepEqual(await pendingReturn, { value: undefined, done: true });
    assert.equal(state.reads, 1);
    assert.equal(state.closes, 1);
  }

  console.log('checks/service.cjs: all scenarios passed');
}

module.exports = main();
